			array( 'checkout_fees', 'fee-field-condition', array( 'wcj_checkout_fees_general_options_tab' ), 'Classic field-dependent fee', 'Classic checkout field name and value conditions are separate from the supported Blocks company condition. Arbitrary field conditions are not generic Blocks support.', 'https://booster.io/docs/woocommerce-checkout-fees/#booster-v10-s15-fee-field-condition', '' ),
