			array( 'payment_gateways', 'custom-inventory', array( 'wcj_payment_gateways_gatways_options_tab' ), 'Custom gateway count and admin identities', 'Count and administrator labels create registered custom gateway identities. The first is jetpack_custom_gateway, followed by numbered IDs starting at 2. Native edition/count limits apply; do not assume the public ten-method description means unlimited in every edition.', 'https://booster.io/docs/woocommerce-custom-payment-gateways/#booster-v10-s15-custom-inventory', '' ),
			array( 'payment_gateways', 'custom-inputs', array(  ), 'Description and shortcode-defined gateway inputs', 'The real WooCommerce gateway Description can contain supported [wcj_input_field] definitions. Classic and Blocks input schemas have separate constraints. Stored answers appear only on applicable authorized order panels; renaming IDs or deleting answers is not an amount-limit edit.', 'https://booster.io/docs/woocommerce-custom-payment-gateways/#booster-v10-s15-custom-inputs', '' ),
			array( 'payment_gateways', 'custom-presentation', array(  ), 'Woo gateway enable, shopper title/description and icon', 'Configure the actual WooCommerce gateway instance: enable, title, description and its own icon. Adding a custom payment option does not connect an online payment processor. These are not the dormant Booster mirror controls.', 'https://booster.io/docs/woocommerce-custom-payment-gateways/#booster-v10-s15-custom-presentation', '' ),
			array( 'payment_gateways', 'custom-instructions', array(  ), 'Order and email instructions', 'WooCommerce instance instructions control applicable order and email output. Verify the actual message and destination without assuming every email or PDF template includes it.', 'https://booster.io/docs/woocommerce-custom-payment-gateways/#booster-v10-s15-custom-instructions', '' ),
