	public static function allowed( $module ) {
		$core = WCJ_Job_Store::core();
		return WCJ_Task_Finder::allowed( $module ) && $core && isset( $core->all_modules[ $module ] );
	}
	public static function native_url( $module, $tab = '', $control = '' ) {
		$url = admin_url( wcj_admin_tab_url() . '&wcj-cat=' . ( 'checkout_fees' === $module ? 'cart_and_checkout' : 'payment_gateways' ) . '&section=' . $module );
		if ( $tab ) { $url = add_query_arg( 'active_tab', $tab, $url ); }
		return $url . ( $control ? '#' . rawurlencode( $control ) : '' );
	}
	private static function link( $url, $label ) { return '<a target="_blank" rel="noopener noreferrer" href="' . esc_url( $url ) . '">' . esc_html( $label . ' (new tab)' ) . '</a>'; }
	/** Resolve real registered Woo instances, not dormant legacy mirror settings. */
	private static function routes( $g ) {
		if ( 'country-guided' === $g[1] ) { return self::link( admin_url( 'admin.php?page=wcj-gateway-country-job' ), 'Open country task' ); }
		if ( 'gateway-fee-guided' === $g[1] ) { return self::link( admin_url( 'admin.php?page=wcj-gateway-fee-job' ), 'Open fee task' ); }
		$woo = in_array( $g[1], array( 'custom-inputs', 'custom-presentation', 'custom-instructions', 'custom-eligibility', 'custom-completion' ), true );
		$dynamic = in_array( 'gateway_dynamic', $g[2], true );
		if ( $woo || $dynamic ) {
			$links = array();
			foreach ( WCJ_Gateway_Amount_Job::gateways() as $id => $gateway ) {
				if ( $woo && ! preg_match( '/^jetpack_custom_gateway(?:_[2-9][0-9]*|_1[0-9]+)?$/D', $id ) ) { continue; }
				$url = $woo ? admin_url( 'admin.php?page=wc-settings&tab=checkout&section=' . $id ) : self::native_url( $g[0], 'wcj_gateways_fees_' . $id . '_tab' );
				if ( $woo ) {
					$fields = array( 'custom-inputs' => 'description', 'custom-presentation' => 'enabled', 'custom-instructions' => 'instructions', 'custom-eligibility' => 'min_amount', 'custom-completion' => 'default_order_status' );
					$url .= '#woocommerce_' . $id . '_' . $fields[ $g[1] ];
				}
				$links[] = self::link( $url, $gateway['title'] . ': ' . ( $woo ? 'WooCommerce instance settings' : 'native fee settings' ) );
			}
			return $links ? implode( ' | ', $links ) : esc_html__( 'No registered instance is available. Review the module count/activation in full settings, then WooCommerce Payments. This page creates nothing.', 'woocommerce-jetpack' ) . ' ' . self::link( self::native_url( $g[0], $woo ? 'wcj_payment_gateways_gatways_options_tab' : 'wcj_gateways_fees_general_options_tab' ), 'Module settings' );
		}
		$links = array(); foreach ( $g[2] ?: array( '' ) as $tab ) { $links[] = self::link( self::native_url( $g[0], $tab, $g[6] ), 'Full settings: ' . $g[3] ); }
		return implode( ' | ', $links );
	}
	public static function render( $module = '', $selected = array() ) {
		$groups = array_filter( self::groups(), static function ( $g ) use ( $module, $selected ) { return ( ! $module || $module === $g[0] ) && ( ! $selected || in_array( $g[1], $selected, true ) ) && self::allowed( $g[0] ); } );
		if ( ! $groups ) { return; }
		echo '<details class="wcj-payment-groups"><summary>' . esc_html__( 'Payment choices: full settings and group help', 'woocommerce-jetpack' ) . '</summary><p>' . esc_html__( 'V10 guidance. Native edition limits and module/role permissions remain in force. Help and editors open in a new tab. Save in the native editor, then deliberately discard and load current values in the amount task. Native saves and resets are not amount Undo.', 'woocommerce-jetpack' ) . '</p><ul>';
		foreach ( $groups as $g ) {
			echo '<li data-payment-group="' . esc_attr( $g[1] ) . '"><h4>' . esc_html( $g[3] ) . '</h4><p>' . esc_html( $g[4] ) . '</p><p>' . self::routes( $g ) . ' | ' . self::link( $g[5], 'Help: ' . $g[3] ) . '</p></li>';
		}
		echo '</ul></details>';
	}
	public static function entry() {
		if ( current_user_can( 'manage_woocommerce' ) ) { echo '<p><a href="' . esc_url( admin_url( 'admin.php?page=wcj-payment-choice-tasks' ) ) . '">' . esc_html__( 'Payment choices, fees and amount limits', 'woocommerce-jetpack' ) . '</a></p>'; }
	}
	public static function register() {
		if ( current_user_can( 'manage_woocommerce' ) ) { add_submenu_page( 'woocommerce', 'Payment choices, fees and amount limits', 'Payment choices', 'manage_woocommerce', 'wcj-payment-choice-tasks', array( __CLASS__, 'hub' ) ); }
	}
	public static function hub() {
		if ( ! current_user_can( 'manage_woocommerce' ) ) { wp_die( 'Ask an administrator for access.', '', array( 'response' => 403 ) ); }
		echo '<div class="wrap"><h1>' . esc_html__( 'Payment choices, fees and amount limits', 'woocommerce-jetpack' ) . '</h1><p>' . esc_html__( 'Choose the outcome. Opening a task never activates a module or payment method. Existing full settings remain available with their native edition limits.', 'woocommerce-jetpack' ) . '</p><nav aria-label="Payment purposes"><a href="#payment-availability">Payment availability</a> | <a href="#payment-fees">Fees and discounts</a> | <a href="#payment-appearance">Appearance and PDF notes</a> | <a href="#payment-custom">Custom payment options</a> | <a href="#payment-why">Why is a method missing?</a></nav>';
		$purposes = array( 'availability' => array( 'Payment availability', array( 'payment_gateways_min_max', 'payment_gateways_by_country', 'payment_gateways_by_currency', 'payment_gateways_by_shipping', 'payment_gateways_by_user_role', 'payment_gateways_per_category' ) ), 'fees' => array( 'Fees and discounts', array( 'payment_gateways_fees', 'checkout_fees' ) ), 'appearance' => array( 'Appearance and PDF notes', array( 'payment_gateways_icons', 'payment_gateways_pdf_notes' ) ), 'custom' => array( 'Add a custom payment option', array( 'payment_gateways' ) ) );
		foreach ( $purposes as $id => $purpose ) {
			echo '<section id="payment-' . esc_attr( $id ) . '"><h2>' . esc_html( $purpose[0] ) . '</h2>';
			if ( 'availability' === $id && self::allowed( 'payment_gateways_min_max' ) ) { echo '<p>' . self::link( WCJ_Gateway_Amount_Job::url(), 'Limit one payment method by cart amount' ) . '</p><p>Free and Plus shortcut: bank transfer. Elite: registered supported methods. Plus native settings for other methods are unchanged.</p>'; }
			if ( 'fees' === $id ) { echo '<p>Checkout Fees remains in Cart &amp; Checkout. It is not the per-method fee engine.</p><p>' . self::link( admin_url( 'admin.php?page=wcj-cart-checkout-tasks' ), 'Cart and checkout tasks' ) . '</p>'; }
			foreach ( $purpose[1] as $module ) { self::render( $module ); }
			echo '</section>';
		}
		echo '<section id="payment-why"><h2>Why is a method missing?</h2><p>Use the existing read-only payment observation. Unknown, not checked, not observed and unsupported are distinct outcomes. One retained rule is not final eligibility. Elite supplied scenarios are not live payment replay.</p>';
		if ( current_user_can( 'manage_woocommerce' ) && class_exists( 'WCJ_Rule_Explanations_Admin' ) ) { echo self::link( admin_url( 'admin.php?page=wcj-rule-explanations' ), 'Existing Rule explanations' ); } else { echo '<p>Ask an administrator for access to the existing diagnostic route.</p>'; }
		echo '</section></div>';
	}
	/** Contextual help on the actual Woo Payments instance editor only. */
	public static function woo_help() {
		$section = isset( $_GET['section'] ) && is_string( $_GET['section'] ) ? sanitize_key( wp_unslash( $_GET['section'] ) ) : '';
		if ( self::allowed( 'payment_gateways' ) && preg_match( '/^jetpack_custom_gateway(?:_[2-9][0-9]*|_1[0-9]+)?$/D', $section ) && isset( WCJ_Gateway_Amount_Job::gateways()[ $section ] ) ) { self::render( 'payment_gateways', array( 'custom-inputs', 'custom-presentation', 'custom-instructions', 'custom-eligibility', 'custom-completion' ) ); }
	}
	/** Attach read-only lifecycle guidance only where the inherited order panel already exists. */
	public static function order_help() {
		global $wp_meta_boxes;
		if ( ! self::allowed( 'payment_gateways' ) ) { return; }
		foreach ( array( 'shop_order', 'woocommerce_page_wc-orders' ) as $screen ) {
			if ( empty( $wp_meta_boxes[ $screen ] ) ) { continue; }
			foreach ( $wp_meta_boxes[ $screen ] as &$contexts ) { foreach ( $contexts as &$boxes ) {
				$id = 'wc-jetpack-payment_gateways';
				if ( empty( $boxes[ $id ] ) || ! is_callable( $boxes[ $id ]['callback'] ) || ! empty( $boxes[ $id ]['wcj_amount_help'] ) ) { continue; }
				$original = $boxes[ $id ]['callback']; $boxes[ $id ]['wcj_amount_help'] = true;
				$boxes[ $id ]['callback'] = static function ( $object, $box ) use ( $original ) {
					$id = is_object( $object ) && is_callable( array( $object, 'get_id' ) ) ? $object->get_id() : ( $object->ID ?? 0 );
					if ( $id && current_user_can( 'edit_shop_order', $id ) && self::allowed( 'payment_gateways' ) ) { self::render( 'payment_gateways', array( 'custom-inputs', 'custom-order-delete' ) ); }
					call_user_func( $original, $object, $box );
				};
			} }
		}
	}

}
add_action( 'admin_menu', array( 'WCJ_Payment_Choice_Groups', 'register' ), 99 );
add_action( 'woocommerce_settings_checkout', array( 'WCJ_Payment_Choice_Groups', 'woo_help' ), 5 );
add_action( 'add_meta_boxes', array( 'WCJ_Payment_Choice_Groups', 'order_help' ), 103 );
